9	// This file defines the Region class.
10	//
11	//===----------------------------------------------------------------------===//
12	
13	#ifndef MLIR_IR_REGION_H
14	#define MLIR_IR_REGION_H
15	
16	#include "mlir/IR/Block.h"
17	
18	namespace mlir {
19	class TypeRange;
20	template <typename ValueRangeT>
21	class ValueTypeRange;
22	class IRMapping;
23	
24	/// This class contains a list of basic blocks and a link to the parent
25	/// operation it is attached to.
26	class Region {
27	public:
28	  Region() = default;
29	  explicit Region(Operation *container);
30	  ~Region();
31	
32	  /// Return the context this region is inserted in.  The region must have a
33	  /// valid parent container.
34	  MLIRContext *getContext();
35	
36	  /// Return a location for this region. This is the location attached to the
37	  /// parent container. The region must have a valid parent container.
38	  Location getLoc();
39	
40	  //===--------------------------------------------------------------------===//
41	  // Block list management
42	  //===--------------------------------------------------------------------===//
43	
44	  using BlockListType = llvm::iplist<Block>;
45	  BlockListType &getBlocks() { return blocks; }
46	  Block &emplaceBlock() {
47	    push_back(new Block);
48	    return back();
49	  }
50	
51	  // Iteration over the blocks in the region.
52	  using iterator = BlockListType::iterator;
53	  using reverse_iterator = BlockListType::reverse_iterator;
54	
55	  iterator begin() { return blocks.begin(); }
56	  iterator end() { return blocks.end(); }
57	  reverse_iterator rbegin() { return blocks.rbegin(); }
58	  reverse_iterator rend() { return blocks.rend(); }
59	
60	  bool empty() { return blocks.empty(); }
61	  void push_back(Block *block) { blocks.push_back(block); }
62	  void push_front(Block *block) { blocks.push_front(block); }
63	
64	  Block &back() { return blocks.back(); }
65	  Block &front() { return blocks.front(); }
66	
67	  /// Return true if this region has exactly one block.
68	  bool hasOneBlock() { return !empty() && std::next(begin()) == end(); }
69	
70	  /// getSublistAccess() - Returns pointer to member of region.
71	  static BlockListType Region::*getSublistAccess(Block *) {
72	    return &Region::blocks;
73	  }
74	
75	  //===--------------------------------------------------------------------===//
76	  // Block numbering
77	  //===--------------------------------------------------------------------===//
78	
79	  /// One past the largest block ID handed out in this region; block IDs lie in
80	  /// [0, getMaxBlockID()). See Block::getBlockID().
81	  unsigned getMaxBlockID() const { return nextBlockID; }
82	
83	  /// The block-ID epoch, part of the generic number-indexed graph contract
84	  /// (LoopInfo, DominatorTree) for detecting stale IDs. MLIR never renumbers a
85	  /// region's blocks, so this is a fixed 0. See Block::getBlockID().
86	  unsigned getBlockIDEpoch() const { return 0; }
87	
88	  //===--------------------------------------------------------------------===//
89	  // Argument Handling
90	  //===--------------------------------------------------------------------===//
91	
92	  // This is the list of arguments to the block.
93	  using BlockArgListType = MutableArrayRef<BlockArgument>;
94	  BlockArgListType getArguments() {
95	    return empty() ? BlockArgListType() : front().getArguments();
96	  }
97	
98	  /// Returns the argument types of the first block within the region.
99	  ValueTypeRange<BlockArgListType> getArgumentTypes();
100	
101	  using args_iterator = BlockArgListType::iterator;
102	  using reverse_args_iterator = BlockArgListType::reverse_iterator;
103	  args_iterator args_begin() { return getArguments().begin(); }
104	  args_iterator args_end() { return getArguments().end(); }
105	  reverse_args_iterator args_rbegin() { return getArguments().rbegin(); }
106	  reverse_args_iterator args_rend() { return getArguments().rend(); }
107	
108	  bool args_empty() { return getArguments().empty(); }
109	
110	  /// Add one value to the argument list.
111	  BlockArgument addArgument(Type type, Location loc) {
112	    return front().addArgument(type, loc);
113	  }
114	
115	  /// Insert one value to the position in the argument list indicated by the
116	  /// given iterator. The existing arguments are shifted. The block is expected
117	  /// not to have predecessors.
118	  BlockArgument insertArgument(args_iterator it, Type type, Location loc) {
119	    return front().insertArgument(it, type, loc);
120	  }
121	
122	  /// Add one argument to the argument list for each type specified in the list.
123	  /// `locs` contains the locations for each of the new arguments, and must be
124	  /// of equal size to `types`.
125	  iterator_range<args_iterator> addArguments(TypeRange types,
126	                                             ArrayRef<Location> locs);
127	
128	  /// Add one value to the argument list at the specified position.
129	  BlockArgument insertArgument(unsigned index, Type type, Location loc) {
130	    return front().insertArgument(index, type, loc);
131	  }
132	
133	  /// Erase the argument at 'index' and remove it from the argument list.
134	  void eraseArgument(unsigned index) { front().eraseArgument(index); }
135	
136	  unsigned getNumArguments() { return getArguments().size(); }
137	  BlockArgument getArgument(unsigned i) { return getArguments()[i]; }
138	
139	  //===--------------------------------------------------------------------===//
140	  // Operation list utilities
141	  //===--------------------------------------------------------------------===//
142	
143	  /// This class provides iteration over the held operations of blocks directly
144	  /// within a region.
145	  class OpIterator final
146	      : public llvm::iterator_facade_base<OpIterator, std::forward_iterator_tag,
147	                                          Operation> {
148	  public:
149	    /// Initialize OpIterator for a region, specify `end` to return the iterator
150	    /// to last operation.
151	    explicit OpIterator(Region *region, bool end = false);
152	
153	    using llvm::iterator_facade_base<OpIterator, std::forward_iterator_tag,
154	                                     Operation>::operator++;
155	    OpIterator &operator++();
156	    Operation *operator->() const { return &*operation; }
157	    Operation &operator*() const { return *operation; }
158	
159	    /// Compare this iterator with another.
160	    bool operator==(const OpIterator &rhs) const {
161	      return operation == rhs.operation;
162	    }
163	    bool operator!=(const OpIterator &rhs) const { return !(*this == rhs); }
164	
165	  private:
166	    void skipOverBlocksWithNoOps();
167	
168	    /// The region whose operations are being iterated over.
169	    Region *region;
170	    /// The block of 'region' whose operations are being iterated over.
171	    Region::iterator block;
172	    /// The current operation within 'block'.
173	    Block::iterator operation;
174	  };
175	
176	  /// This class provides iteration over the held operations of a region for a
177	  /// specific operation type.
178	  template <typename OpT>
179	  using op_iterator = detail::op_iterator<OpT, OpIterator>;
180	
181	  /// Return iterators that walk the operations nested directly within this
182	  /// region.
183	  OpIterator op_begin() { return OpIterator(this); }
184	  OpIterator op_end() { return OpIterator(this, /*end=*/true); }
185	  iterator_range<OpIterator> getOps() { return {op_begin(), op_end()}; }
186	
187	  /// Return iterators that walk operations of type 'T' nested directly within
188	  /// this region.
189	  template <typename OpT>
190	  op_iterator<OpT> op_begin() {
191	    return detail::op_filter_iterator<OpT, OpIterator>(op_begin(), op_end());
192	  }
193	  template <typename OpT>
194	  op_iterator<OpT> op_end() {
195	    return detail::op_filter_iterator<OpT, OpIterator>(op_end(), op_end());
196	  }
197	  template <typename OpT>
198	  iterator_range<op_iterator<OpT>> getOps() {
199	    auto endIt = op_end();
200	    return {detail::op_filter_iterator<OpT, OpIterator>(op_begin(), endIt),
201	            detail::op_filter_iterator<OpT, OpIterator>(endIt, endIt)};
202	  }
203	
204	  //===--------------------------------------------------------------------===//
205	  // Misc. utilities
206	  //===--------------------------------------------------------------------===//
207	
208	  /// Return the region containing this region or nullptr if the region is
209	  /// attached to a top-level operation.
210	  Region *getParentRegion();
211	
212	  /// Return the parent operation this region is attached to.
213	  Operation *getParentOp() { return container; }
214	
215	  /// Return true if this region is attached to an operation.
216	  bool isAttached() { return container != nullptr; }
217	
218	  /// Find the first parent operation of the given type, or nullptr if there is
219	  /// no ancestor operation.
220	  template <typename ParentT>
221	  ParentT getParentOfType() {
222	    auto *region = this;
223	    do {
224	      if (auto parent = dyn_cast_or_null<ParentT>(region->container))
225	        return parent;
226	    } while ((region = region->getParentRegion()));
227	    return ParentT();
228	  }
229	  template <typename... ParentT>
230	  std::enable_if_t<(sizeof...(ParentT) > 1), Operation *> getParentOfType() {
231	    auto *region = this;
232	    do {
233	      if (!region->container)
234	        return nullptr;
235	      if (isa<ParentT...>(region->container))
236	        return region->container;
237	    } while ((region = region->getParentRegion()));
238	    return nullptr;
239	  }
240	
241	  /// Return the number of this region in the parent operation.
242	  unsigned getRegionNumber();
243	
244	  /// Return true if this region is a proper ancestor of the `other` region.
245	  bool isProperAncestor(Region *other);
246	
247	  /// Return true if this region is ancestor of the `other` region.  A region
248	  /// is considered as its own ancestor, use `isProperAncestor` to avoid this.
249	  bool isAncestor(Region *other) {
250	    return this == other || isProperAncestor(other);
251	  }
252	
253	  /// Clone the internal blocks from this region into dest. Any
254	  /// cloned blocks are appended to the back of dest. If the mapper
255	  /// contains entries for block arguments, these arguments are not included
256	  /// in the respective cloned block.
257	  ///
258	  /// Calling this method from multiple threads is generally safe if through the
259	  /// process of cloning, no new uses of 'Value's from outside the region are
260	  /// created. Using the mapper, it is possible to avoid adding uses to outside
261	  /// operands by remapping them to 'Value's owned by the caller thread.
262	  void cloneInto(Region *dest, IRMapping &mapper);
263	  /// Clone this region into 'dest' before the given position in 'dest'.
264	  void cloneInto(Region *dest, Region::iterator destPos, IRMapping &mapper);
265	
266	  /// Takes body of another region (that region will have no body after this
267	  /// operation completes).  The current body of this region is cleared.
268	  void takeBody(Region &other) {
269	    dropAllReferences();
270	    blocks.clear();
271	    blocks.splice(blocks.end(), other.getBlocks());
272	  }
273	
274	  /// Returns 'block' if 'block' lies in this region, or otherwise finds the
275	  /// ancestor of 'block' that lies in this region. Returns nullptr if the
276	  /// latter fails.
277	  Block *findAncestorBlockInRegion(Block &block);
278	
279	  /// Returns 'op' if 'op' lies in this region, or otherwise finds the
280	  /// ancestor of 'op' that lies in this region. Returns nullptr if the
281	  /// latter fails.
282	  Operation *findAncestorOpInRegion(Operation &op);
283	
284	  /// Drop all operand uses from operations within this region, which is
285	  /// an essential step in breaking cyclic dependences between references when
286	  /// they are to be deleted.
287	  void dropAllReferences();
288	
289	  //===--------------------------------------------------------------------===//
290	  // Walkers
291	  //===--------------------------------------------------------------------===//
292	
293	  /// Walk all nested operations, blocks or regions (including this region),
294	  /// depending on the type of callback.
295	  ///
296	  /// The order in which operations, blocks or regions at the same nesting
297	  /// level are visited (e.g., lexicographical or reverse lexicographical order)
298	  /// is determined by `Iterator`. The walk order for enclosing operations,
299	  /// blocks or regions with respect to their nested ones is specified by
300	  /// `Order` (post-order by default).
301	  ///
302	  /// A callback on a operation or block is allowed to erase that operation or
303	  /// block if either:
304	  ///   * the walk is in post-order, or
305	  ///   * the walk is in pre-order and the walk is skipped after the erasure.
306	  ///
307	  /// See Operation::walk for more details.
308	  template <WalkOrder Order = WalkOrder::PostOrder,
309	            typename Iterator = ForwardIterator, typename FnT,
310	            typename ArgT = detail::first_argument<FnT>,
311	            typename RetT = detail::walkResultType<FnT>>
312	  RetT walk(FnT &&callback) {
313	    if constexpr (std::is_same<ArgT, Region *>::value &&
314	                  Order == WalkOrder::PreOrder) {
315	      // Pre-order walk on regions: invoke the callback on this region.
316	      if constexpr (std::is_same<RetT, void>::value) {
317	        callback(this);
318	      } else {
319	        RetT result = callback(this);
320	        if (result.wasSkipped())
321	          return WalkResult::advance();
322	        if (result.wasInterrupted())
323	          return WalkResult::interrupt();
324	      }
325	    }
326	
327	    // Walk nested operations, blocks or regions.
328	    for (auto &block : *this) {
329	      if constexpr (std::is_same<RetT, void>::value) {
330	        block.walk<Order, Iterator>(callback);
331	      } else {
332	        if (block.walk<Order, Iterator>(callback).wasInterrupted())
333	          return WalkResult::interrupt();
334	      }
335	    }
336	
337	    if constexpr (std::is_same<ArgT, Region *>::value &&
338	                  Order == WalkOrder::PostOrder) {
339	      // Post-order walk on regions: invoke the callback on this block.
340	      return callback(this);
341	    }
342	    if constexpr (!std::is_same<RetT, void>::value)
343	      return WalkResult::advance();
344	  }
345	
346	  //===--------------------------------------------------------------------===//
347	  // CFG view utilities
348	  //===--------------------------------------------------------------------===//
349	
350	  /// Displays the CFG in a window. This is for use from the debugger and
351	  /// depends on Graphviz to generate the graph.
352	  /// This function is defined in ViewOpGraph.cpp and only works with that
353	  /// target linked.
354	  void viewGraph(const Twine &regionName);
355	  void viewGraph();
356	
357	private:
358	  BlockListType blocks;
359	
360	  /// This is the object we are part of.
361	  Operation *container = nullptr;
362	
363	  /// Next block ID to hand out. See Block::getBlockID().
364	  unsigned nextBlockID = 0;
365	
366	  friend struct llvm::ilist_traits<Block>;
367	};
368	
369	/// This class provides an abstraction over the different types of ranges over
370	/// Regions. In many cases, this prevents the need to explicitly materialize a
371	/// SmallVector/std::vector. This class should be used in places that are not
372	/// suitable for a more derived type (e.g. ArrayRef) or a template range
373	/// parameter.
374	class RegionRange
375	    : public llvm::detail::indexed_accessor_range_base<
376	          RegionRange,
377	          PointerUnion<Region *, const std::unique_ptr<Region> *, Region **>,
378	          Region *, Region *, Region *> {
379	  /// The type representing the owner of this range. This is either an owning
380	  /// list of regions, a list of region unique pointers, or a list of region
381	  /// pointers.
382	  using OwnerT =
383	      PointerUnion<Region *, const std::unique_ptr<Region> *, Region **>;
384	
385	public:
386	  using RangeBaseT::RangeBaseT;
387	
388	  RegionRange(MutableArrayRef<Region> regions = {});
389	
390	  template <typename Arg, typename = std::enable_if_t<std::is_constructible<
391	                              ArrayRef<std::unique_ptr<Region>>, Arg>::value>>
392	  RegionRange(Arg &&arg LLVM_LIFETIME_BOUND)
393	      : RegionRange(ArrayRef<std::unique_ptr<Region>>(std::forward<Arg>(arg))) {
394	  }
395	  template <typename Arg>
396	  RegionRange(
397	      Arg &&arg LLVM_LIFETIME_BOUND,
398	      std::enable_if_t<std::is_constructible<ArrayRef<Region *>, Arg>::value>
399	          * = nullptr)
400	      : RegionRange(ArrayRef<Region *>(std::forward<Arg>(arg))) {}
401	  RegionRange(ArrayRef<std::unique_ptr<Region>> regions);
402	  RegionRange(ArrayRef<Region *> regions);
403	
404	private:
405	  /// See `llvm::detail::indexed_accessor_range_base` for details.
406	  static OwnerT offset_base(const OwnerT &owner, ptrdiff_t index);
407	  /// See `llvm::detail::indexed_accessor_range_base` for details.
408	  static Region *dereference_iterator(const OwnerT &owner, ptrdiff_t index);
409	
410	  /// Allow access to `offset_base` and `dereference_iterator`.
411	  friend RangeBaseT;
412	};
413	
414	llvm::raw_ostream &operator<<(llvm::raw_ostream &os, Region &region);
415	
416	} // namespace mlir
417	
418	#endif // MLIR_IR_REGION_H
